(() => {
'use strict';
const $ = (s,root=document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modules=window.COURSE, exercises=window.EXERCISES, lessons=modules.flatMap(m=>m.lessons.map(l=>({...l,module:m})));
const lessonMap=new Map(lessons.map(l=>[l.id,l])), exerciseMap=new Map(exercises.map(e=>[e.id,e]));
const KEY='java-trail-progress-v1';
const empty=()=>({version:1,name:'',goal:2,completed:{},solved:{},quizPassed:{},bookmarks:[],notes:{},drafts:{},hints:{},activity:{},seconds:0,lastLesson:'hello'});
let storageOK=true;
function normalize(raw){
 if(!raw || raw.version!==1 || typeof raw!=='object') throw Error('Please choose a Java Trail progress backup.');
 const s=empty(), obj=v=>v&&typeof v==='object'&&!Array.isArray(v);
 s.name=typeof raw.name==='string'?raw.name.slice(0,40):'';
 s.goal=[1,2,3,5].includes(raw.goal)?raw.goal:2;
 for(const id of lessonMap.keys()){
  if(typeof raw.completed?.[id]==='string'&&!Number.isNaN(Date.parse(raw.completed[id])))s.completed[id]=raw.completed[id];
  if(raw.quizPassed?.[id]===true)s.quizPassed[id]=true;
  if(typeof raw.notes?.[id]==='string')s.notes[id]=raw.notes[id].slice(0,10000);
 }
 for(const id of exerciseMap.keys()){
  const solved=raw.solved?.[id];
  if(obj(solved)&&typeof solved.at==='string'&&!Number.isNaN(Date.parse(solved.at)))s.solved[id]={at:solved.at};
  if(typeof raw.drafts?.[id]==='string')s.drafts[id]=raw.drafts[id].slice(0,15000);
  if(Number.isInteger(raw.hints?.[id]))s.hints[id]=Math.max(0,Math.min(3,raw.hints[id]));
 }
 s.bookmarks=Array.isArray(raw.bookmarks)?[...new Set(raw.bookmarks.filter(id=>lessonMap.has(id)))]:[];
 if(obj(raw.activity))for(const [k,v]of Object.entries(raw.activity))if(/^\d{4}-\d{2}-\d{2}$/.test(k)&&Number.isFinite(v)&&v>0)s.activity[k]=Math.min(1000,Math.floor(v));
 s.seconds=Number.isFinite(raw.seconds)?Math.max(0,Math.min(raw.seconds,1e9)):0;
 if(lessonMap.has(raw.lastLesson))s.lastLesson=raw.lastLesson;
 return s;
}
let state;
try { const raw=localStorage.getItem(KEY); state=raw?normalize(JSON.parse(raw)):empty(); }catch(e){ state=empty(); storageOK=false; }
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;}updateChrome();}
function dayKey(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function dateAgo(n){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-n);return d;}
function streak(){let n=0,offset=state.activity[dayKey()]?0:1;for(let i=offset;i<36500;i++){if(!state.activity[dayKey(dateAgo(i))])break;n++;}return n;}
const totalItems=lessons.length+exercises.length;
const doneCount=()=>Object.keys(state.completed).length+Object.keys(state.solved).length;
const percent=()=>Math.round(doneCount()/totalItems*100);
function activity(){const key=dayKey();state.activity[key]=(state.activity[key]||0)+1;}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3500);}
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',learn:'<path d="M3 5c4-2 6-2 9 0 3-2 5-2 9 0v15c-4-2-6-2-9 0-3-2-5-2-9 0Z"/><path d="M12 5v15"/>',practice:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',progress:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',saved:'<path d="M6 3h12v18l-6-4-6 4Z"/>',resources:'<path d="M4 3h13v17H4Zm4 4h5m-5 4h5m7-5v15H7"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.learn}</svg>`;
let currentRoute='',filter='All',search='',runController=null,runBusy=false;
const runResults={};
function updateChrome(){
 const page=currentRoute.split('/')[0]||'overview';
 const nav=[['overview','Overview','#/'],['learn','Learning path','#/learn'],['practice','Coding practice','#/practice'],['progress','My progress','#/progress'],['saved','Saved lessons','#/saved'],['resources','Resources','#/resources']];
 $('#navigation').innerHTML=nav.map(([id,title,url])=>`<a class="nav-item ${page===id||(page==='lesson'&&id==='learn')||(page==='exercise'&&id==='practice')?'active':''}" href="${url}" ${page===id?'aria-current="page"':''}>${icon(id)}${title}${id==='practice'?`<span class="count">${exercises.length}</span>`:''}</a>`).join('');
 $('#sidebar-progress').innerHTML=`<div class="bar"><span style="width:${percent()}%"></span></div><div class="progress-label"><span>${doneCount()} of ${totalItems} milestones</span><strong>${percent()}%</strong></div>`;
 $('#streak-pill').innerHTML=`♨ <span>${streak()} day streak</span>`;
 $('#save-status').innerHTML=storageOK?'<i></i> Progress saved locally':'<i style="background:#ee9d6b"></i> Storage unavailable — download a backup';
}
function heading(eyebrow,title,sub,action=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function stats(){return `<div class="stats"><div class="stat"><span class="stat-icon">▤</span><div><strong>${Object.keys(state.completed).length}<em> / ${lessons.length}</em></strong><small>Lessons completed</small></div></div><div class="stat"><span class="stat-icon">⌘</span><div><strong>${Object.keys(state.solved).length}<em> / ${exercises.length}</em></strong><small>Scenarios solved</small></div></div><div class="stat"><span class="stat-icon">◷</span><div><strong>${Math.floor(state.seconds/60)}<em> min</em></strong><small>Active learning time</small></div></div><div class="stat"><span class="stat-icon">↗</span><div><strong>${percent()}<em> %</em></strong><small>Overall progress</small></div></div></div>`;}
function tag(level){return `<span class="tag ${level==='Intermediate'?'orange':level==='Advanced'?'blue':''}">${level}</span>`;}
function moduleCard(m){const done=m.lessons.filter(l=>state.completed[l.id]).length;return `<a href="#/lesson/${m.lessons.find(l=>!state.completed[l.id])?.id||m.lessons[0].id}" class="module-card"><div class="module-main"><span class="module-number">${m.icon}</span><div class="module-info"><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="module-meta">${tag(m.level)}<span class="dot"></span><span>${m.lessons.length} lessons</span><span class="dot"></span><span>${m.lessons.reduce((a,l)=>a+l.minutes,0)} min</span></div></div><div class="module-end"><span>${done===m.lessons.length?'Completed ✓':`${done}/${m.lessons.length} done`}</span><div class="bar"><span style="width:${done/m.lessons.length*100}%"></span></div></div><span class="module-arrow">↗</span></div></a>`;}
function nextLesson(){const last=lessonMap.get(state.lastLesson);return last&&!state.completed[last.id]?last:lessons.find(l=>!state.completed[l.id])||lessons[0];}
function weekDots(){const today=new Date().getDay(),monday=(today+6)%7;return `<div class="week-dots">${Array.from({length:7},(_,i)=>{const d=dateAgo(monday-i),key=dayKey(d);return `<div class="${state.activity[key]?'done ':''}${key===dayKey()?'today':''}"><span>${state.activity[key]?'✓':d.getDate()}</span><small>${['M','T','W','T','F','S','S'][i]}</small></div>`;}).join('')}</div>`;}
function overview(){
 const next=nextLesson(),today=state.activity[dayKey()]||0;
 const firstModules=[...modules.filter(m=>!m.lessons.every(l=>state.completed[l.id])),...modules.filter(m=>m.lessons.every(l=>state.completed[l.id]))].slice(0,4);
 return `${heading('A LITTLE PROGRESS, EVERY DAY',`${state.name?`Welcome back, ${esc(state.name)}`:'Your Java journey starts here'}<span style="color:#7d9cff">.</span>`,'From your first line of code to your next big idea. Let’s keep moving.',`<a class="button secondary" href="#/learn">View learning path <span>↗</span></a>`)}
 <section class="hero"><div class="hero-grid" aria-hidden="true"></div><div class="hero-orbit" aria-hidden="true"><i></i><i></i><i></i></div><div class="hero-copy"><span class="eyebrow">${doneCount()?'YOUR NEXT SMALL WIN':'YOUR NEXT CHAPTER'}</span><h2>${doneCount()?esc(next.title):'Build your next<br><span class="hero-accent">version.</span>'}</h2><p>${doneCount()?`Keep going with ${esc(next.module.title.toLowerCase())}. Your next lesson is about ${next.minutes} minutes away.`:'Master the language. Solve real challenges. Turn your curiosity into code.'}</p><a class="button light" href="#/lesson/${next.id}">${doneCount()?'Continue learning':'Start your first lesson'} <span>→</span></a></div><div class="hero-code"><div class="code-window"><div class="window-bar"><i class="window-dot"></i><i class="window-dot"></i><i class="window-dot"></i><span>YourJourney.java</span></div><pre><span class="code-num">1</span><span class="code-key">class</span> YourJourney {
<span class="code-num">2</span>  <span class="code-key">public static void</span> main(String[] args) {
<span class="code-num">3</span>    <span class="code-comment">// Every expert was a beginner.</span>
<span class="code-num">4</span>    System.out.println(<span class="code-str">"You've got this."</span>);
<span class="code-num">5</span>  }
<span class="code-num">6</span>}</pre><div class="run-tag"><i></i> A small step today. A new possibility tomorrow.</div></div></div></section>
 ${stats()}<div class="dashboard-grid"><section><div class="section-title"><div><h2>Your learning path</h2><p>A clear route from the basics to building real things.</p></div><a href="#/learn">All ${modules.length} modules ↗</a></div><div class="module-list">${firstModules.map(moduleCard).join('')}</div><div class="practice-banner"><div><h3>A little less reading. A little more doing.</h3><p>Real-life scenarios, a Java editor, and a hint when you need one.</p></div><a class="button" href="#/practice">Try a challenge →</a></div></section><aside class="dashboard-aside"><div class="side-card"><h3>Your daily goal <span style="float:right;color:#90a6ff">◎</span></h3><div class="goal-ring" style="--progress:${Math.min(today/state.goal,1)*360}deg"><div><strong>${Math.min(today,state.goal)}<span style="font-size:13px;color:#a3af97">/${state.goal}</span></strong><small>milestones today</small></div></div><p class="goal-description">${today>=state.goal?'Goal reached. Nice work showing up.':'A lesson or a solved scenario counts.<br>Small steps add up.'}</p>${weekDots()}</div><div class="side-card tip"><span class="tip-icon">☼</span><span class="eyebrow">A GOOD LEARNING HABIT</span><h3>Get curious. Get it wrong.</h3><p>Try a solution before opening a hint. A mistake is a useful clue about what to learn next.</p><a class="text-link" href="#/exercise/${exercises.find(e=>!state.solved[e.id])?.id||'coffee'}">Put it into practice <span>↗</span></a></div></aside></div>`;
}
function toolbar(placeholder){return `<div class="toolbar"><div class="tabs" role="group" aria-label="Filter by level">${['All','Beginner','Intermediate','Advanced'].map(f=>`<button class="tab ${filter===f?'active':''}" data-filter="${f}" aria-pressed="${filter===f}">${f==='All'?'All levels':f}</button>`).join('')}</div><input class="search" type="search" aria-label="${placeholder}" placeholder="⌕  ${placeholder}" value="${esc(search)}" id="search"></div>`;}
function matches(m){return (filter==='All'||m.level===filter)&&`${m.title} ${m.description} ${m.lessons?.map(l=>l.title).join(' ')||m.topic}`.toLowerCase().includes(search.toLowerCase());}
function learn(){const selected=modules.filter(matches);return `${heading('YOUR CURRICULUM','A path. Not a pile of tutorials.',`${modules.length} modules · ${lessons.length} lessons · Beginner to advanced. Learn at your own pace.`)}${toolbar('Search topics or lessons')}<div class="course-grid" id="filter-results">${selected.map(m=>`<section class="course-module"><div class="course-module-head"><span class="module-number">${m.icon}</span><div>${tag(m.level)}<h3>${esc(m.title)}</h3></div></div><p>${esc(m.description)}</p>${m.lessons.map(l=>lessonLink(l)).join('')}</section>`).join('')||emptyMessage('No topics found','Try a different topic or level.')}</div>`;}
function lessonLink(l,current=false){return `<a class="lesson-link ${current?'current':''}" href="#/lesson/${l.id}"><span class="lesson-status ${state.completed[l.id]?'done':''}">${state.completed[l.id]?'✓':'›'}</span><span>${esc(l.title)}</span><small>${l.minutes} min</small></a>`;}
function emptyMessage(title,desc,link=''){return `<div class="empty"><h2>${title}</h2><p>${desc}</p>${link}</div>`;}
function renderLesson(id){const l=lessonMap.get(id);if(!l)return notFound();state.lastLesson=id;save();const idx=lessons.indexOf(l),passed=state.quizPassed[id],done=state.completed[id];const relevant=exercises.find(e=>e.related===id)||exercises.find(e=>e.level===l.module.level&&!state.solved[e.id]);
 return `<a class="back-link" href="#/learn">← Back to the learning path</a><div class="lesson-layout"><article class="lesson-content"><div class="button-row">${tag(l.module.level)}<span class="tiny muted">Module ${l.module.icon} · ${l.minutes} min read</span><button class="bookmark-button ${state.bookmarks.includes(id)?'selected':''}" id="bookmark" data-id="${id}" style="margin-left:auto" aria-pressed="${state.bookmarks.includes(id)}">${state.bookmarks.includes(id)?'★ Saved':'☆ Save lesson'}</button></div><h1>${esc(l.title)}</h1><p class="intro">${esc(l.intro)}</p><h2>What to keep in mind</h2><ul class="takeaways">${l.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><h2>See it in code</h2><p class="tiny muted">Examples show the relevant snippet. Comments identify required imports, setup, or method placement.</p><div class="example"><div class="example-head"><span>Java · worked example</span><button id="copy-code" data-id="${id}">Copy code</button></div><pre><code>${esc(l.code)}</code></pre><div class="example-output">${esc(l.output)}</div></div><div class="callout"><strong>A useful detail</strong><br>${esc(l.tip)}</div><a class="resource-link" href="${l.module.docs}" target="_blank" rel="noopener noreferrer">Go deeper in the official documentation ↗</a><section class="quiz"><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><h3>${esc(l.quiz.question)}</h3><form id="quiz-form" data-id="${id}">${l.quiz.options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="answer" value="${i}" ${passed&&i===l.quiz.answer?'checked':''} required> ${esc(o)}</label>`).join('')}<button class="button small" style="margin-top:9px">Check answer →</button></form><div id="quiz-feedback" aria-live="polite">${passed?`<div class="feedback success">✓ ${esc(l.quiz.explanation)}</div>`:''}</div></section><h2 class="notes-label"><label for="lesson-notes">Your notes</label><small class="tiny muted">Saved as you type</small></h2><textarea id="lesson-notes" class="notes" data-id="${id}" maxlength="10000" placeholder="A useful example, a question, or something you want to remember…">${esc(state.notes[id]||'')}</textarea><div class="lesson-footer"><span class="tiny muted">${done?'✓ Lesson completed. You can revisit it anytime.':'Pass the knowledge check, then mark this lesson complete.'}</span><button class="button" id="complete-lesson" data-id="${id}" ${!passed||done?'disabled':''}>${done?'Completed ✓':'Complete lesson ✓'}</button></div><div class="button-row" style="justify-content:space-between;margin-top:22px">${idx>0?`<a class="text-link" href="#/lesson/${lessons[idx-1].id}">← Previous lesson</a>`:'<span></span>'}${idx<lessons.length-1?`<a class="text-link" href="#/lesson/${lessons[idx+1].id}">Next lesson →</a>`:'<a class="text-link" href="#/progress">See your progress →</a>'}</div></article><aside><div class="side-card outline"><span class="eyebrow">MODULE ${l.module.icon}</span><h3>${esc(l.module.title)}</h3>${l.module.lessons.map(item=>lessonLink(item,item.id===id)).join('')}${relevant?`<div class="spacer"></div><span class="eyebrow">TRY A REAL SCENARIO</span><h3 style="margin-top:9px">${esc(relevant.title)}</h3><p class="tiny" style="margin:10px 0 17px">Write the code. Run the tests. Reveal a hint if you get stuck.</p><a class="button secondary small" href="#/exercise/${relevant.id}">Open coding practice →</a>`:''}</div></aside></div>`;
}
function practice(){const selected=exercises.filter(matches);return `${heading('LEARN BY DOING','Small scenarios. Real Java.',`${exercises.length} hands-on challenges. Write a solution, run real tests, and learn from the result.`)}<div class="callout" style="margin-top:-5px">Start with a scenario that feels approachable. Every exercise includes sample cases, three progressive hints, and an explained path through the code.</div>${toolbar('Search coding scenarios')}<div class="exercise-grid" id="filter-results">${selected.map(e=>`<a href="#/exercise/${e.id}" class="exercise-card"><div class="card-top"><span class="code-symbol">&lt;/&gt;</span>${state.solved[e.id]?'<span class="tag complete">✓ Solved</span>':tag(e.level)}</div><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><div class="card-bottom"><span>${esc(e.topic)}</span><span>${state.solved[e.id]?'Practice again':'Start coding'} ↗</span></div></a>`).join('')||emptyMessage('No scenarios found','Try another keyword or difficulty.')}</div>`;}
function testsTable(e,result){return `<table class="tests"><thead><tr><th>Test case</th><th>Expected</th><th>Actual</th><th>Status</th></tr></thead><tbody>${e.tests.map((t,i)=>`<tr><td title="${esc(t[0])}">${esc(t[2])}<br><span class="muted" style="font-size:8px">${esc(t[0])}</span></td><td>${esc(t[1])}</td><td>${result?.actual?.[i]!==undefined?esc(result.actual[i]):'—'}</td><td class="${result?.passed?.[i]?'test-pass':result?.passed?'test-fail':''}">${result?.passed?(result.passed[i]?'✓ Pass':'✕ Fail'):'Not run'}</td></tr>`).join('')}</tbody></table>`;}
function hintPanel(e){const n=state.hints[e.id]||0;return `${e.hints.slice(0,n).map((h,i)=>`<details class="hint" ${i===n-1?'open':''}><summary>Hint ${i+1} · ${['A nudge','The approach','A little more help'][i]}</summary><p>${esc(h)}</p></details>`).join('')}${n<3?`<button class="button secondary small hint-button" id="reveal-hint" data-id="${e.id}">☼ Reveal hint ${n+1} of 3</button>`:'<p class="tiny" style="margin-top:13px">All three hints are open. Take it one step at a time.</p>'}${n===3?`<details class="solution"><summary>Still stuck? Reveal a reference solution</summary><p style="font-size:10px;margin-top:9px">Compare the approach with your own. Revealing this does not complete the exercise.</p><pre>${esc(e.solution)}</pre></details>`:''}`;}
function renderExercise(id){const e=exerciseMap.get(id);if(!e)return notFound();const result=runResults[id];return `<a class="back-link" href="#/practice">← Back to coding practice</a><div class="workspace"><section class="scenario-panel">${tag(e.level)}${state.solved[id]?'<span class="tag complete" style="margin-left:7px">✓ Previously solved</span>':''}<h1>${esc(e.title)}</h1><p>${esc(e.description)}</p><h3>Your mission</h3><p>${esc(e.task)}</p><h3>The method to implement</h3><code>${esc(e.signature)}</code><ul><li>Edit the supplied method or class, not a full main program.</li><li>java.util, java.util.stream, java.time, and java.math imports are included.</li><li>${e.id==='report'?'The Task record is supplied for you.':'All example cases must pass to solve the scenario.'}</li></ul><a class="resource-link" href="#/lesson/${e.related}">Review the related lesson →</a><h3>A hint, when you need it <span style="float:right;color:#9caeff">☼</span></h3><div id="hints">${hintPanel(e)}</div></section><div><section class="editor-panel"><div class="editor-top"><span>Solution.java</span><small>OpenJDK 21 · real Java</small></div><div class="editor-help">Write your solution below. Tab indents · Ctrl / ⌘ + Enter runs tests</div><label for="code-editor" class="sr-only">Java solution for ${esc(e.title)}</label><textarea id="code-editor" class="editor" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" data-id="${id}" maxlength="15000">${esc(state.drafts[id]??e.starter)}</textarea><div class="editor-actions"><span id="draft-status">Draft saved automatically</span><div class="button-row"><button class="button ghost small" id="reset-code" data-id="${id}">Reset code</button><button class="button light" id="run-code" data-id="${id}">▷ Run tests</button></div></div></section><section class="test-panel"><h3>Test results <span id="test-score" style="float:right;font-size:10px;color:#9baee2">${result?.passed?`${result.passed.filter(Boolean).length} / ${e.tests.length} passed`:`${e.tests.length} example cases`}</span></h3><p>Each case calls your method with a different input.</p><div id="test-results" aria-live="polite">${testsTable(e,result)}${result?.message?`<pre class="console">${esc(result.message)}</pre>`:''}</div><div class="compiler-note">Runs on <a href="https://wandbox.org" target="_blank" rel="noopener noreferrer">Wandbox</a> with OpenJDK 21. Your code is sent to that service only when you run tests. An internet connection and compiler availability are required. These example cases check the stated behavior; they are not exhaustive.</div></section></div></div>`;}
function progress(){const heat=Array.from({length:84},(_,i)=>{const d=dateAgo(83-i),count=state.activity[dayKey(d)]||0;return `<div class="heat-cell ${count>=4?'l3':count>=2?'l2':count?'l1':''}" role="img" aria-label="${dayKey(d)}: ${count} milestones" title="${dayKey(d)} · ${count} milestones"></div>`;}).join('');const achievements=[['✦','The first step','Complete your first lesson.',Object.keys(state.completed).length>=1],['⌘','Problem solver','Pass every test in a coding scenario.',Object.keys(state.solved).length>=1],['♨','A little consistency','Complete milestones on 3 consecutive days.',longestStreak()>=3],['⌁','A solid foundation','Complete all 12 beginner lessons.',lessons.filter(l=>l.module.level==='Beginner').every(l=>state.completed[l.id])],['◇','Trail explorer','Complete the full course and all scenarios.',doneCount()===totalItems]];
return `${heading('LOOK HOW FAR YOU CAN GO','Your progress, made visible.','Every lesson learned and problem solved is a step forward.',`<button class="button secondary" data-export>Download backup ↓</button>`)}${stats()}<div class="progress-grid"><section class="panel"><h2>Course mastery</h2><p>Completed lessons in each module. Revisit any topic whenever you need a refresher.</p>${modules.map(m=>{const done=m.lessons.filter(l=>state.completed[l.id]).length;return `<a class="progress-module" href="#/lesson/${m.lessons[0].id}"><span class="module-number">${m.icon}</span><div><strong>${esc(m.title)}</strong><div class="bar"><span style="width:${done/m.lessons.length*100}%"></span></div></div><span>${done}/${m.lessons.length}</span></a>`;}).join('')}</section><div><section class="panel"><h2>Keep showing up</h2><p>Your last 12 weeks. A completed lesson or newly solved scenario adds one milestone.</p><div class="heatmap">${heat}</div><div class="heatmap-label"><span>12 weeks ago</span><span>Today</span></div><div class="spacer"></div><div class="button-row"><span class="tag">${streak()} day current streak</span><span class="tag orange">${longestStreak()} day best streak</span></div></section><div class="spacer"></div><section class="panel"><h2>Milestones along the way</h2>${achievements.map(([i,title,desc,earned])=>`<div class="achievement ${earned?'earned':''}"><span class="achievement-icon">${i}</span><div><h3>${title} ${earned?'✓':''}</h3><p>${desc}</p></div></div>`).join('')}</section><div class="spacer"></div><section class="panel"><h2>Coding practice</h2><p>${Object.keys(state.solved).length} of ${exercises.length} scenarios solved with passing tests.</p><div class="bar"><span style="width:${Object.keys(state.solved).length/exercises.length*100}%"></span></div><div class="spacer"></div><a class="text-link" href="#/practice">Find your next scenario ↗</a></section></div></div>`;}
function longestStreak(){const keys=Object.keys(state.activity).sort();let best=0,current=0,prev=null;for(const key of keys){const d=new Date(key+'T12:00:00');if(prev){const next=new Date(prev);next.setDate(next.getDate()+1);current=dayKey(next)===key?current+1:1;}else current=1;best=Math.max(best,current);prev=d;}return best;}
function saved(){const list=lessons.filter(l=>state.bookmarks.includes(l.id));return `${heading('YOUR PERSONAL REFERENCE SHELF','Keep the useful bits close.','Saved lessons and the notes you leave for your future self.')}<div class="course-grid">${list.length?list.map(l=>`<a class="course-module" href="#/lesson/${l.id}"><span class="eyebrow">${esc(l.module.title)}</span><h3 style="margin:11px 0">${esc(l.title)}</h3><p>${esc(state.notes[l.id]||l.intro).slice(0,190)}…</p><span class="text-link">Revisit lesson →</span></a>`).join(''):emptyMessage('A place for your “aha” moments.','Tap “Save lesson” inside any lesson to keep it here.',`<a class="button" href="#/learn">Explore the learning path →</a>`)}</div>`;}
function resources(){const links=[['START HERE','Dev.java learning hub','Official tutorials, from your first program to collections, virtual threads, and the JVM.','https://dev.java/learn/','dev.java'],['LOOK SOMETHING UP','Java 21 API reference','The source of truth for standard library classes, methods, contracts, and exceptions.','https://docs.oracle.com/en/java/javase/21/docs/api/','docs.oracle.com'],['GET YOUR TOOLKIT','OpenJDK builds','Find JDK builds and the tools you need to compile and run Java locally.','https://jdk.java.net/','jdk.java.net'],['TEST WITH CONFIDENCE','JUnit user guide','Learn assertions, parameterized tests, and how to run a repeatable test suite.','https://docs.junit.org/current/user-guide/','docs.junit.org'],['BUILD & PACKAGE','Maven getting started','Create a project, manage dependencies, run tests, and package your application.','https://maven.apache.org/guides/getting-started/','maven.apache.org'],['EXPLORE THE LANGUAGE','Java language updates','See which features belong to each release, and distinguish final features from previews.','https://docs.oracle.com/en/java/javase/25/language/','docs.oracle.com']];return `${heading('GO A LITTLE DEEPER','Good references. Better questions.','A small collection of primary sources to keep beside your editor.')}<div class="resources">${links.map(([tag,title,desc,url,site])=>`<a class="resource-card" href="${url}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">${tag}</span><h3>${title} ↗</h3><p>${desc}</p><small>${site}</small></a>`).join('')}</div><div class="callout">Course examples target Java 21. Snippets may require the imports or setup shown in their comments. JUnit, JDBC drivers, databases, and build tools are separate from the online practice runner.</div>`;}
function settings(){return `${heading('MAKE IT YOURS','A learning rhythm that fits.','Set a small goal and keep a copy of your progress.')}<div class="settings-grid"><section class="panel"><h2>Your learning preferences</h2><form id="preferences"><div class="field"><label for="display-name">What should we call you?</label><input id="display-name" name="name" value="${esc(state.name)}" maxlength="40" placeholder="Your first name" autocomplete="given-name"></div><div class="field"><label for="daily-goal">Daily milestone goal</label><select name="goal" id="daily-goal">${[1,2,3,5].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} milestone${n>1?'s':''} a day</option>`).join('')}</select><p class="hint-text">Completing a lesson or solving a new coding scenario counts as one milestone.</p></div><button class="button">Save preferences</button></form></section><section class="panel"><h2>Your progress belongs to you.</h2><p>Lessons, solutions, code drafts, hints, notes, and activity are saved in this browser. They stay here after you close the app.</p><p>Progress does not automatically sync between devices. Download a backup, then import it in another browser to continue there.</p><div class="button-row"><button class="button secondary" data-export>Download backup ↓</button><label class="button secondary" for="import-file" style="cursor:pointer">Import backup ↑</label><input class="sr-only" type="file" id="import-file" accept="application/json,.json"></div><p class="hint-text">Import replaces the current browser’s progress. A backup of the current progress is downloaded first.</p><p class="hint-text">Active learning time counts while this tab is visible and you have interacted within the last five minutes. Streaks use your device’s local dates.</p></section></div><section class="panel danger-zone"><h2>A fresh start</h2><p>Clear your progress and drafts from this browser. This cannot be undone without a backup.</p><button class="button secondary" id="reset-progress">Reset my progress</button></section>`;}
function notFound(){return emptyMessage('That trail isn’t here.','Choose a lesson or scenario from your learning path.',`<a class="button" href="#/">Back to overview →</a>`);}
function render(keepScroll=false){
 const [page='',id]=currentRoute.split('/');
 const renderers={'':overview,overview,learn,practice,progress,saved,resources,settings,lesson:()=>renderLesson(id),exercise:()=>renderExercise(id)};
 $('#main').innerHTML=(renderers[page]||notFound)();
 const title=page==='lesson'?lessonMap.get(id)?.title:page==='exercise'?exerciseMap.get(id)?.title:({'':'Overview',learn:'Learning path',practice:'Coding practice',progress:'My progress',saved:'Saved lessons',resources:'Resources',settings:'Settings'}[page]||'Overview');
 document.title=`${title} · Java Trail`;
 $('#breadcrumb').innerHTML=`Your workspace / <strong>${esc(title)}</strong>`;
 updateChrome();
 if(!keepScroll)window.scrollTo({top:0});
 bindPage();
}
function route(){if(runController)runController.abort();currentRoute=location.hash.replace(/^#\/?/,'');filter='All';search='';$('#sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');render();}
function bindPage(){
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render(true);});
 const searchInput=$('#search');if(searchInput)searchInput.oninput=()=>{search=searchInput.value;const pos=searchInput.selectionStart;render(true);$('#search').focus();$('#search').setSelectionRange(pos,pos);};
 const bookmark=$('#bookmark');if(bookmark)bookmark.onclick=()=>{const id=bookmark.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();render(true);};
 const copy=$('#copy-code');if(copy)copy.onclick=async()=>{try{await navigator.clipboard.writeText(lessonMap.get(copy.dataset.id).code);toast('Example copied.');}catch(e){toast('Select the example text to copy it.');}};
 const q=$('#quiz-form');if(q)q.onsubmit=event=>{event.preventDefault();const l=lessonMap.get(q.dataset.id),correct=Number(new FormData(q).get('answer'))===l.quiz.answer;$('#quiz-feedback').innerHTML=`<div class="feedback ${correct?'success':'error'}">${correct?'✓':'Try once more.'} ${esc(correct?l.quiz.explanation:'Review the key ideas above, then choose another answer.')}</div>`;if(correct){state.quizPassed[l.id]=true;save();if(!state.completed[l.id])$('#complete-lesson').disabled=false;}};
 const notes=$('#lesson-notes');if(notes)notes.oninput=()=>{state.notes[notes.dataset.id]=notes.value;save();};
 const complete=$('#complete-lesson');if(complete)complete.onclick=()=>{const id=complete.dataset.id;if(!state.quizPassed[id]||state.completed[id])return;state.completed[id]=new Date().toISOString();activity();save();render(true);toast('Lesson complete. One more step forward!');};
 const hints=$('#reveal-hint');if(hints)hints.onclick=()=>{const id=hints.dataset.id;state.hints[id]=Math.min(3,(state.hints[id]||0)+1);save();$('#hints').innerHTML=hintPanel(exerciseMap.get(id));bindHint();};
 function bindHint(){const b=$('#reveal-hint');if(b)b.onclick=()=>{state.hints[b.dataset.id]=Math.min(3,(state.hints[b.dataset.id]||0)+1);save();$('#hints').innerHTML=hintPanel(exerciseMap.get(b.dataset.id));bindHint();};}
 const editor=$('#code-editor');if(editor){editor.oninput=()=>{state.drafts[editor.dataset.id]=editor.value;save();$('#draft-status').textContent=storageOK?'Draft saved automatically':'Storage unavailable — download a backup';};editor.onkeydown=event=>{if(event.key==='Tab'){event.preventDefault();const start=editor.selectionStart,end=editor.selectionEnd;editor.setRangeText('    ',start,end,'end');editor.dispatchEvent(new Event('input'));}if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();if(!runBusy)runExercise(editor.dataset.id);}};}
 const run=$('#run-code');if(run)run.onclick=()=>{if(runBusy){runController?.abort();}else runExercise(run.dataset.id);};
 const reset=$('#reset-code');if(reset)reset.onclick=()=>{const e=exerciseMap.get(reset.dataset.id);if($('#code-editor').value!==e.starter&&!confirm('Replace your current code with the starter? Your solved status will be kept.'))return;state.drafts[e.id]=e.starter;delete runResults[e.id];save();render(true);};
 document.querySelectorAll('[data-export]').forEach(b=>b.onclick=exportProgress);
 const prefs=$('#preferences');if(prefs)prefs.onsubmit=event=>{event.preventDefault();const data=new FormData(prefs);state.name=String(data.get('name')).trim().slice(0,40);state.goal=Number(data.get('goal'));save();toast('Your learning rhythm is set.');};
 const imp=$('#import-file');if(imp)imp.onchange=async()=>{const file=imp.files[0];if(!file)return;try{if(file.size>3e6)throw Error('This file is too large for a progress backup.');const imported=normalize(JSON.parse(await file.text()));exportProgress();state=imported;save();render(true);toast('Backup imported. Your previous progress was downloaded first.');}catch(e){toast(e.message||'This backup could not be read.');}finally{imp.value='';}};
 const resetProgress=$('#reset-progress');if(resetProgress)resetProgress.onclick=()=>$('#confirm-dialog').showModal();
}
function exportProgress(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`java-trail-progress-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function buildHarness(e,code,marker){return `import java.util.*;\nimport java.util.stream.*;\nimport java.time.*;\nimport java.math.*;\nclass Main {\n${code}\n${window.EXERCISE_HELPERS[e.id]||''}\npublic static void main(String[] args) {\n${e.tests.map((t,i)=>`try { System.out.println("${marker}${i}__" + String.valueOf(${t[0]})); } catch (Throwable ex) { System.out.println("${marker}${i}__THREW:" + ex.getClass().getSimpleName()); }`).join('\n')}\n}\n}`;}
async function runExercise(id){
 const e=exerciseMap.get(id),editor=$('#code-editor');if(!e||!editor||runBusy)return;
 const code=editor.value;if(!code.trim()){toast('Add a Java solution first.');return;}
 state.drafts[id]=code;save();runBusy=true;runController=new AbortController();const controller=runController;
 const marker='__JT_'+Math.random().toString(36).slice(2)+'_';
 const button=$('#run-code');button.innerHTML='<span class="loading-dot"></span> Cancel run';$('#reset-code').disabled=true;
 $('#test-results').innerHTML='<p role="status" style="padding:20px 0">Compiling your Java and running the example cases…</p>';
 const timer=setTimeout(()=>controller.abort('timeout'),40000);
 try{
  const response=await fetch('https://wandbox.org/api/compile.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({compiler:'openjdk-jdk-21+35',code:buildHarness(e,code,marker),save:false}),signal:controller.signal});
  if(!response.ok)throw Error(response.status===429?'The compiler is busy. Please wait a moment, then try again.':`The compiler service returned HTTP ${response.status}. Please try again shortly.`);
  const data=await response.json();
  if(String(data.status)!=='0'){
   runResults[id]={message:(data.compiler_error||data.compiler_message||data.program_error||data.program_message||'The compiler could not finish this run. Check the code and try again.').slice(0,12000)};
  }else{
   const output=String(data.program_output||''),actual=e.tests.map((_,i)=>{const prefix=marker+i+'__';const line=output.split(/\r?\n/).find(s=>s.startsWith(prefix));return line?line.slice(prefix.length):'(no result)';});
   const passed=actual.map((s,i)=>s.trim()===e.tests[i][1]);
   const all=passed.every(Boolean);runResults[id]={actual,passed,message:all?'All example cases passed. Nice problem solving!':'Some cases need another look. Compare expected and actual values, then try a hint.'};
   if(all&&!state.solved[id]){state.solved[id]={at:new Date().toISOString()};activity();save();toast('Scenario solved! Your progress is saved.');}
  }
 }catch(error){runResults[id]={message:controller.signal.aborted?(controller.signal.reason==='timeout'?'This run timed out. Check for an infinite loop, or try again when the compiler is available.':'Run cancelled. Your draft is saved.'):(error.message==='Failed to fetch'?'Could not reach the Java compiler. Check your internet connection or try again later. Your draft is saved.':error.message)};}
 finally{clearTimeout(timer);runBusy=false;if(runController===controller)runController=null;if(currentRoute===`exercise/${id}`)render(true);}
}
$('#mobile-menu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#mobile-menu').setAttribute('aria-expanded',String(open));};
document.addEventListener('click',event=>{if(window.innerWidth<=760&&!event.target.closest('#sidebar')&&!event.target.closest('#mobile-menu')){$('#sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');}});
$('#confirm-dialog').addEventListener('close',()=>{if($('#confirm-dialog').returnValue==='reset'){state=empty();for(const k of Object.keys(runResults))delete runResults[k];save();render();toast('A fresh trail. Your progress has been reset.');}});
let lastInteraction=Date.now();for(const type of ['pointerdown','keydown','scroll'])document.addEventListener(type,()=>{lastInteraction=Date.now();},{passive:true});
setInterval(()=>{if(document.visibilityState==='visible'&&Date.now()-lastInteraction<300000){state.seconds+=15;save();}},15000);
window.addEventListener('storage',event=>{if(event.key===KEY&&event.newValue){try{state=normalize(JSON.parse(event.newValue));if(!$('textarea:focus'))render(true);}catch(e){}}});
window.addEventListener('hashchange',route);route();
if(!storageOK)setTimeout(()=>toast('Browser storage is unavailable. Download a backup to keep your progress.'),800);
// Pure harness exposed for integrity checks; no progress is changed by it.
window.JavaTrail={buildHarness,normalize};
})();
